import {createServer} from 'node:http';
export async function githubService({repository='o/r',sourceRevision='b'.repeat(40)}={}){
 const state={releases:[],assets:new Map(),latest:null,tag:null,next:1,failures:{},writes:[]};
 const server=createServer(async(req,res)=>{try{const url=new URL(req.url,'http://fixture'),route=url.pathname.replace('/repos/'+repository,'');let bytes=Buffer.alloc(0);for await(const chunk of req)bytes=Buffer.concat([bytes,chunk]);const body=bytes.length&&req.headers['content-type']==='application/json'?JSON.parse(bytes):null;const send=(status,value)=>{res.writeHead(status,{'content-type':'application/json'});res.end(JSON.stringify(value));};const mutation=req.method!=='GET';if(mutation)state.writes.push({method:req.method,route,body});
  if(route.startsWith('/git/ref/'))return state.tag?send(200,{object:{type:'commit',sha:state.tag}}):send(404,{});
  if(route==='/releases/latest')return state.latest?send(200,state.releases.find(r=>r.id===state.latest)):send(404,{});
  if(route==='/releases'&&req.method==='GET')return send(200,state.releases);
  if(route==='/releases'&&req.method==='POST'){if(state.failures.createBefore){state.failures.createBefore--;return send(500,{});}const r={id:state.next++,draft:true,prerelease:false,...body,upload_url:origin+'/uploads/'+state.next+'{?name,label}',html_url:'https://github.com/'+repository+'/releases/tag/'+body.tag_name,published_at:null};r.upload_url=origin+'/uploads/'+r.id+'{?name,label}';state.releases.push(r);if(state.failures.createLost){state.failures.createLost--;req.socket.destroy();return;}return send(201,r);}
  const upload=url.pathname.match(/^\/uploads\/(\d+)$/);if(upload&&req.method==='POST'){const id=Number(upload[1]),name=url.searchParams.get('name'),r=state.releases.find(r=>r.id===id),list=state.assets.get(id)??[];if(list.some(a=>a.name===name))return send(422,{});if(state.failures.uploadBefore){state.failures.uploadBefore--;return send(500,{});}const a={id:state.next++,name,size:bytes.length,state:'uploaded',url:origin+'/asset/'+state.next,browser_download_url:'https://github.com/'+repository+'/releases/download/'+r.tag_name+'/'+name,body:bytes};a.url=origin+'/asset/'+a.id;list.push(a);state.assets.set(id,list);if(state.failures.uploadStarter){state.failures.uploadStarter--;a.state='starter';a.size=0;a.body=Buffer.alloc(0);return send(502,{});}if(state.failures.uploadLost){state.failures.uploadLost--;req.socket.destroy();return;}return send(201,a);}
  const binary=url.pathname.match(/^\/asset\/(\d+)$/);if(binary){const a=[...state.assets.values()].flat().find(a=>a.id===Number(binary[1]));if(!a)return send(404,{});res.end(a.body);return;}
  const asset=route.match(/^\/releases\/assets\/(\d+)$/);if(asset&&req.method==='DELETE'){for(const [id,list]of state.assets)state.assets.set(id,list.filter(a=>a.id!==Number(asset[1])));res.writeHead(204);res.end();return;}
  const match=route.match(/^\/releases\/(\d+)(\/assets)?$/);if(match){const r=state.releases.find(r=>r.id===Number(match[1]));if(!r)return send(404,{});if(match[2])return send(200,(state.assets.get(r.id)??[]).map(({body,...a})=>a));if(req.method==='GET')return send(200,r);if(req.method==='PATCH'){if(body.draft===false&&state.failures.publishBefore){state.failures.publishBefore--;return send(500,{});}if(body.make_latest==='true'&&state.failures.promoteBefore){state.failures.promoteBefore--;return send(500,{});}Object.assign(r,body);if(body.draft===false){r.published_at='2026-10-31T00:00:00Z';state.tag=sourceRevision;}if(body.make_latest==='true')state.latest=r.id;if(state.failures.publishLost&&body.draft===false){state.failures.publishLost--;req.socket.destroy();return;}return send(200,r);}}
  send(404,{});
 }catch{res.writeHead(500);res.end('{}');}});await new Promise(r=>server.listen(0,'127.0.0.1',r));const origin='http://127.0.0.1:'+server.address().port;return {origin,state,close:()=>new Promise(r=>server.close(r))};
}
